#!/usr/bin/env bash
# Meridian self-contained installer; generated by tools/package-installer.sh.
set -euo pipefail
case "${1:-}" in
    --help|-h)
        echo 'Usage: sudo bash meridian-installer.run [installer option]'
        echo 'Without options: install Meridian and Debian runtime dependencies.'
        echo 'Options: --check-build (no root), --uninstall, --try-login-screen,'
        echo '         --enable-login-screen, --disable-login-screen, --full-codecs'
        exit 0 ;;
    ''|--check-build|--uninstall|--try-login-screen|--enable-login-screen|--disable-login-screen|--full-codecs) ;;
    *) echo "Unknown option: $1" >&2; exit 2 ;;
esac
[ "$#" -le 1 ] || { echo 'Expected at most one option.' >&2; exit 2; }
if [ "${1:-}" != --check-build ] && [ "$(id -u)" != 0 ]; then
    echo 'Run this installer with sudo bash, or use --check-build to verify it.' >&2
    exit 1
fi
umask 077
bundle_tmp="$(mktemp -d)"
trap 'rm -rf -- "$bundle_tmp"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
payload_line="$(awk '/^__MERIDIAN_PAYLOAD__$/ { print NR + 1; exit }' "$0")"
[ -n "$payload_line" ] || { echo 'Missing installer payload.' >&2; exit 1; }
tail -n +"$payload_line" "$0" > "$bundle_tmp/payload.tar.gz"
printf '%s  %s\n' '@PAYLOAD_SHA256@' "$bundle_tmp/payload.tar.gz" | sha256sum --check --status || {
    echo 'Installer is damaged: payload checksum failed.' >&2; exit 1;
}
mkdir "$bundle_tmp/release"
tar -xzf "$bundle_tmp/payload.tar.gz" --no-same-owner -C "$bundle_tmp/release"
bash "$bundle_tmp/release/tools/install.sh" "$@"
exit $?
__MERIDIAN_PAYLOAD__
